simplesect.para:
BAD_FUNC_ARG NULLキーが渡された場合に返されます。 Example DsaKeykey;
intret;
ret=wc_InitDsaKey(&key);//initializeDSAkey

none いいえ返します。 Example DsaKeykey;
//initializekey,useforauthentication
...
wc_FreeDsaKey(&key);//freeDSAkey

parameterdescription.para:
署名を生成するための初期化されたDsakey構造へのポインタ Example DsaKeykey;
//initializeDSAkey,loadprivateKey
intret;
WC_RNGrng;
wc_InitRng(&rng);
bytehash[]={//initializewithhashdigest};
bytesignature[40];//signaturewillbe40bytes(320bits)

ret=wc_DsaSign(hash,signature,&key,&rng);
if(ret!=0){
//errorgeneratingDSAsignature
}

署名を検証するための初期化されたDsakey構造へのポインタ Example DsaKeykey;
//initializeDSAkey,loadpublicKey

intret;
intverified;
bytehash[]={//initializewithhashdigest};
bytesignature[]={//initializewithsignaturetoverify};
ret=wc_DsaVerify(hash,signature,&key,&verified);
if(ret!=0){
