公開鍵を保存するDsakey構造へのポインタ Example intret,idx=0;

DsaKeykey;
wc_InitDsaKey(&key);
bytederBuff[]={//DSApublickey};
ret=wc_DsaPublicKeyDecode(derBuff,&idx,&key,inSz);
if(ret!=0){
//errorreadingpublickey
}

秘密鍵を保存するDSakey構造へのポインタ Example intret,idx=0;

DsaKeykey;
wc_InitDsaKey(&key);
bytederBuff[]={//DSAprivatekey};
ret=wc_DsaPrivateKeyDecode(derBuff,&idx,&key,inSz);
if(ret!=0){
//errorreadingprivatekey
}

変換キーの出力バッファへのポインタ。 Example DsaKeykey;
WC_WC_RNGrng;
intderSz;
intbufferSize=//Sufficientbuffersize;
byteder[bufferSize];

wc_InitDsaKey(&key);
wc_InitRng(&rng);
wc_MakeDsaKey(&rng,&key);
derSz=wc_DsaKeyToDer(&key,der,bufferSize);

WC_RNG構造体へのポインタ。 Example WC_WC_RNGrng;
DsaKeydsa;
wc_InitRng(&rng);
wc_InitDsa(&dsa);
if(wc_MakeDsaKey(&rng,&dsa)!=0)
{
//Errorcreatingkey
}

1024,2048、または3072は有効な値です。 Example DsaKeykey;
WC_WC_RNGrng;
wc_InitDsaKey(&key);
wc_InitRng(&rng);
if(wc_MakeDsaParameters(&rng,1024,&genKey)!=0)
